"""Generate modules/azure/naming from the NamingStandard policy (single source of truth)."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from tf_factory.naming import fixture_cases, render_name
from tf_factory.policy import naming_policy, repo_root_from


GENERATED_BANNER = (
    "# GENERATED by `tf-factory generate-naming` — do not edit by hand.\n"
    "# Source of truth: policies NamingStandard (naming.yaml / naming.example.yaml).\n"
)


def _tf_string_map(data: dict[str, str], indent: int = 4) -> str:
    pad = " " * indent
    lines = ["{"]
    for key in sorted(data):
        lines.append(f'{pad}{key} = "{data[key]}"')
    lines.append("}")
    return "\n".join(lines)


def generate_naming_module(
    policies_dir: Path,
    output_dir: Path | None = None,
) -> Path:
    root = repo_root_from(policies_dir)
    policy = naming_policy(policies_dir)
    out = output_dir or (root / "modules" / "azure" / "naming")
    out.mkdir(parents=True, exist_ok=True)

    prefixes: dict[str, str] = dict(policy.get("resource_prefixes") or {})
    regions: dict[str, str] = dict(policy.get("regions") or {})
    constraints: dict[str, Any] = dict(policy.get("resource_constraints") or {})
    environments = list(policy.get("environments") or ["dev", "test", "staging", "prod"])

    # Expected outputs for terraform test / parity
    expected = []
    for case in fixture_cases(policy):
        expected.append(
            {
                **case,
                "expected": render_name(
                    policy,
                    case["resource_type"],
                    workload=case["workload"],
                    env=case["env"],
                    region=case["region"],
                    suffix=case["suffix"],
                ),
            }
        )
    (out / "expected_names.json").write_text(
        json.dumps(expected, indent=2) + "\n", encoding="utf-8"
    )

    variables_tf = f"""{GENERATED_BANNER}
variable "workload" {{
  type        = string
  description = "Short workload or application identifier (no spaces)."
}}

variable "environment" {{
  type        = string
  description = "Environment code."

  validation {{
    condition     = contains({json.dumps(environments)}, var.environment)
    error_message = "environment must be one of: {', '.join(environments)}."
  }}
}}

variable "region" {{
  type        = string
  description = "Azure region name (e.g. eastus). Mapped to a short code from policy."
}}

variable "suffix" {{
  type        = string
  description = "Numeric or short disambiguator — always preserved when truncating."
  default     = "01"
}}

variable "resource_prefixes" {{
  type        = map(string)
  description = "Override prefixes (defaults generated from NamingStandard policy)."
  default     = {_tf_string_map(prefixes)}
}}

variable "region_codes" {{
  type        = map(string)
  description = "Override region codes (defaults generated from NamingStandard policy)."
  default     = {_tf_string_map(regions)}
}}
"""

    # Constraint locals for types we specially handle
    kv_max = int((constraints.get("key_vault") or {}).get("max_length") or 24)
    st_max = int((constraints.get("storage_account") or {}).get("max_length") or 24)
    pe_max = int((constraints.get("private_endpoint") or {}).get("max_length") or 64)
    rg_max = int((constraints.get("resource_group") or {}).get("max_length") or 90)

    main_tf = f"""{GENERATED_BANNER}
/**
 * Policy-generated Azure naming helpers.
 *
 * Truncation preserves prefix, environment, region, and suffix.
 * Only the workload segment is shortened. Names never end with "-".
 */

locals {{
  region_code = lookup(
    var.region_codes,
    var.region,
    replace(lower(var.region), "/[^a-z0-9]/", "")
  )

  workload_alnum = replace(lower(var.workload), "/[^a-z0-9]/", "")
  workload_hyphen = replace(lower(var.workload), "/[^a-z0-9-]/", "")

  # --- storage_account (no hyphens, max {st_max}) ---
  st_prefix = var.resource_prefixes["storage_account"]
  st_fixed_len = length(local.st_prefix) + length(var.environment) + length(local.region_code) + length(var.suffix)
  st_budget = max({st_max} - local.st_fixed_len, 0)
  st_workload = substr(local.workload_alnum, 0, local.st_budget)
  storage_account = "${{local.st_prefix}}${{local.st_workload}}${{var.environment}}${{local.region_code}}${{var.suffix}}"

  # --- key_vault (hyphenated, max {kv_max}) ---
  kv_prefix = var.resource_prefixes["key_vault"]
  kv_overhead = length(local.kv_prefix) + length(var.environment) + length(local.region_code) + length(var.suffix) + 4
  kv_budget = max({kv_max} - local.kv_overhead, 0)
  kv_workload = substr(local.workload_hyphen, 0, local.kv_budget)
  key_vault = join("-", compact([
    local.kv_prefix,
    local.kv_workload,
    var.environment,
    local.region_code,
    var.suffix,
  ]))

  # --- private_endpoint (hyphenated, max {pe_max}) ---
  pe_prefix = var.resource_prefixes["private_endpoint"]
  pe_overhead = length(local.pe_prefix) + length(var.environment) + length(local.region_code) + length(var.suffix) + 4
  pe_budget = max({pe_max} - local.pe_overhead, 0)
  pe_workload = substr(local.workload_hyphen, 0, local.pe_budget)
  private_endpoint = join("-", compact([
    local.pe_prefix,
    local.pe_workload,
    var.environment,
    local.region_code,
    var.suffix,
  ]))

  # --- resource_group and other hyphenated types (max {rg_max} for rg; others uncapped here) ---
  rg_prefix = var.resource_prefixes["resource_group"]
  rg_overhead = length(local.rg_prefix) + length(var.environment) + length(local.region_code) + length(var.suffix) + 4
  rg_budget = max({rg_max} - local.rg_overhead, 0)
  rg_workload = substr(local.workload_hyphen, 0, local.rg_budget)
  resource_group = join("-", compact([
    local.rg_prefix,
    local.rg_workload,
    var.environment,
    local.region_code,
    var.suffix,
  ]))

  hyphenated_other = {{
    for type, prefix in var.resource_prefixes :
    type => join("-", compact([
      prefix,
      local.workload_hyphen,
      var.environment,
      local.region_code,
      var.suffix,
    ]))
    if !contains(["storage_account", "key_vault", "private_endpoint", "resource_group"], type)
  }}

  names = merge(local.hyphenated_other, {{
    resource_group   = local.resource_group
    storage_account  = local.storage_account
    key_vault        = local.key_vault
    private_endpoint = local.private_endpoint
  }})
}}
"""

    outputs_tf = f"""{GENERATED_BANNER}
output "region_code" {{
  description = "Resolved short region code."
  value       = local.region_code
}}

output "names" {{
  description = "Map of resource_type → rendered name."
  value       = local.names
}}

output "resource_group" {{
  description = "Resource group name."
  value       = local.names["resource_group"]
}}

output "storage_account" {{
  description = "Storage account name (no hyphens; suffix preserved)."
  value       = local.names["storage_account"]
}}

output "key_vault" {{
  description = "Key Vault name (suffix preserved; no trailing hyphen)."
  value       = local.names["key_vault"]
}}

output "private_endpoint" {{
  description = "Private Endpoint name."
  value       = local.names["private_endpoint"]
}}
"""

    versions_tf = f"""{GENERATED_BANNER}
terraform {{
  required_version = ">= 1.5.0"
}}
"""

    readme = """# azure/naming

**Generated** from the NamingStandard policy by `tf-factory generate-naming`.

Do not edit `main.tf` / `variables.tf` / `outputs.tf` by hand. Change the policy, then regenerate:

```bash
tf-factory generate-naming --policies ./policies
```

## Truncation rules

- Preserves **prefix**, **environment**, **region**, and **suffix**
- Shortens only the **workload** segment
- Never leaves a leading/trailing `-`
- Different suffixes must not collide when fixed segments fit in `max_length`

## Parity

`expected_names.json` is written from the same Python `render_name` used by `tf-factory render-name`.
`terraform test` and `factory/tests/test_naming_parity.py` assert Python and Terraform agree.
"""

    (out / "variables.tf").write_text(variables_tf, encoding="utf-8")
    (out / "main.tf").write_text(main_tf, encoding="utf-8")
    (out / "outputs.tf").write_text(outputs_tf, encoding="utf-8")
    (out / "versions.tf").write_text(versions_tf, encoding="utf-8")
    (out / "README.md").write_text(readme, encoding="utf-8")

    # terraform test file
    tests_dir = out / "tests"
    tests_dir.mkdir(exist_ok=True)
    test_cases_hcl = []
    for i, case in enumerate(expected):
        if case["resource_type"] not in {"key_vault", "storage_account", "private_endpoint"}:
            continue
        attr = case["resource_type"]
        test_cases_hcl.append(
            f"""
run "case_{i}_{case['resource_type']}_{case['suffix']}" {{
  command = plan

  variables {{
    workload    = "{case['workload']}"
    environment = "{case['env']}"
    region      = "{case['region']}"
    suffix      = "{case['suffix']}"
  }}

  assert {{
    condition     = output.{attr} == "{case['expected']}"
    error_message = "expected {case['expected']}, got ${{output.{attr}}}"
  }}
}}
"""
        )

    (tests_dir / "naming.tftest.hcl").write_text(
        GENERATED_BANNER + "\n".join(test_cases_hcl),
        encoding="utf-8",
    )

    return out
